#!name=罗森点点
#!desc=某些APP要清除缓存或者重新安装拦截广告才会生效！
#!author=奶思
#!homepage=https://github.com/fmz200/wool_scripts
#!icon=https://raw.githubusercontent.com/fmz200/wool_scripts/main/icons/gif/naisi-01.gif
#!raw-url=https://github.com/fmz200/wool_scripts/raw/main/Loon/plugin/split/partL/LuoSenDianDian.lpx
#!tg-channel=https://t.me/inaisi
#!date=2026-11-11 21:17:23
#############################################


[Argument]
lawson_enable = switch,true,false,tag=罗森点点-脚本开关

[Rewrite]
request if ${url} ~= /^https:\/\/plt\.yorentown\.com\/pltapp\/v1\/banner/i then reject_dict(200)


[Script]
response if ${url} ~= /^https:\/\/lawsonapi\.yorentown\.com\/area\/sh-lawson\/app\/v1\//i then script("https://raw.githubusercontent.com/fmz200/wool_scripts/main/Scripts/lawson.js") with enable=${lawson_enable}, tag="罗森点点", timeout=60, requires_body=true
response if ${url} ~= /^https:\/\/lawsonapi\.yorentown\.com\/portal\/app\/globalLaunch\/listAdvert/i then script("https://raw.githubusercontent.com/fmz200/wool_scripts/main/Scripts/lawson.js") with enable=${lawson_enable}, tag="罗森点点", timeout=60, requires_body=true


[MITM]
hostname = plt.yorentown.com, lawsonapi.yorentown.com
